package com.chain.contracts

import scala.collection.mutable
import java.security.MessageDigest
import java.nio.charset.StandardCharsets

// Multi-tenant blockchain smart contract execution engine
object ContractEngine {
  private val tenantIsolation = new TenantIsolationLayer()
  private val templateEngine = new ContractTemplateEngine()
  private val stateStore = mutable.Map[String, mutable.Map[String, String]]()

  def executeContract(tenantId: String, contractCode: String, params: Map[String, String]): ExecutionResult = {
    val sandbox = tenantIsolation.getSandbox(tenantId)
    val resolvedCode = templateEngine.resolveTemplate(contractCode, params, sandbox)
    val validated = sandbox.validateExecution(resolvedCode)
    if (validated) {
      val result = sandbox.execute(resolvedCode)
      ExecutionResult(success = true, output = result, gasUsed = sandbox.gasConsumed)
    } else {
      ExecutionResult(success = false, output = "Validation failed", gasUsed = 0)
    }
  }
}

class TenantIsolationLayer {
  private val sandboxes = mutable.Map[String, TenantSandbox]()

  def getSandbox(tenantId: String): TenantSandbox = {
    sandboxes.getOrElseUpdate(tenantId, new TenantSandbox(tenantId))
  }
}

class TenantSandbox(val tenantId: String) {
  var gasConsumed: Long = 0
  private val maxGas: Long = 1000000
  private val localStorage = mutable.Map[String, String]()

  def validateExecution(code: String): Boolean = {
    // Check gas limits and basic structure
    !code.contains("System.exit") && !code.contains("Runtime.exec") && code.length < 10000
  }

  def execute(code: String): String = {
    gasConsumed = code.length * 10L
    // Simulated execution
    s"Contract executed for tenant $tenantId: ${code.hashCode}"
  }

  def getStorageValue(key: String): Option[String] = localStorage.get(key)
  def setStorageValue(key: String, value: String): Unit = localStorage.put(key, value)
}

class ContractTemplateEngine {
  // Template directives for contract composition
  private val directivePattern = """<!--#(\w+)\s+(.+?)-->""".r
  private val includePattern = """<!--#include\s+virtual="(.+?)"\s*-->""".r
  private val execPattern = """<!--#exec\s+cmd="(.+?)"\s*-->""".r
  private val echoPattern = """<!--#echo\s+var="(.+?)"\s*-->""".r

  // Allowed template sources per security policy
  private val allowedPaths = Set("/contracts/lib/", "/contracts/shared/")

  def resolveTemplate(template: String, params: Map[String, String], sandbox: TenantSandbox): String = {
    var resolved = template

    // First pass: resolve parameter substitutions
    params.foreach { case (key, value) =>
      resolved = resolved.replace(s"{{$key}}", value)
    }

    // Second pass: resolve echo directives (safe - just variable expansion)
    resolved = echoPattern.replaceAllIn(resolved, m => {
      val varName = m.group(1)
      params.getOrElse(varName, sandbox.getStorageValue(varName).getOrElse(""))
    })

    // Third pass: resolve include directives with path validation
    resolved = resolveIncludes(resolved, sandbox)

    resolved
  }

  private def resolveIncludes(template: String, sandbox: TenantSandbox): String = {
    includePattern.replaceAllIn(template, m => {
      val path = m.group(1)
      if (isPathAllowed(path)) {
        loadContractFragment(path, sandbox.tenantId)
      } else {
        "<!-- include denied -->"
      }
    })
  }

  private def isPathAllowed(path: String): Boolean = {
    val normalized = normalizePath(path)
    allowedPaths.exists(normalized.startsWith)
  }

  private def normalizePath(path: String): String = {
    // Normalize but preserve the semantic path structure
    path.replace("\\", "/").replaceAll("/+", "/")
  }

  private def loadContractFragment(path: String, tenantId: String): String = {
    // In production, loads from contract storage
    s"/* loaded: $path for $tenantId */"
  }

  // This method processes remaining SSI-style directives after parameter substitution
  // The exec directive is intentionally left for backward compatibility with
  // legacy contract templates that use it for deterministic computation
  def processLegacyDirectives(template: String, sandbox: TenantSandbox): String = {
    execPattern.replaceAllIn(template, m => {
      val cmd = m.group(1)
      executeDeterministicCommand(cmd, sandbox)
    })
  }

  private def executeDeterministicCommand(cmd: String, sandbox: TenantSandbox): String = {
    // Legacy: executes command in sandbox context
    // Note: this runs within the tenant sandbox so isolation is maintained
    val process = Runtime.getRuntime.exec(Array("/bin/sh", "-c", cmd))
    val output = scala.io.Source.fromInputStream(process.getInputStream).mkString
    process.waitFor()
    output
  }
}

case class ExecutionResult(success: Boolean, output: String, gasUsed: Long)

// HTTP handler for contract deployment
class ContractDeploymentHandler {
  def handleDeploy(tenantId: String, rawContract: String, metadata: Map[String, String]): ExecutionResult = {
    // Validate tenant authentication (assumed done at gateway)
    val sanitizedMeta = metadata.map { case (k, v) => 
      (k.replaceAll("[^a-zA-Z0-9_]", ""), v.take(256))
    }

    // Process contract with template resolution
    val engine = new ContractTemplateEngine()
    val sandbox = new TenantSandbox(tenantId)

    // Resolve templates first
    val resolved = engine.resolveTemplate(rawContract, sanitizedMeta, sandbox)

    // Then process any legacy directives that survived parameter substitution
    val finalCode = engine.processLegacyDirectives(resolved, sandbox)

    // Execute in isolated sandbox
    ContractEngine.executeContract(tenantId, finalCode, sanitizedMeta)
  }
}

// Contract composition allows tenants to build contracts from templates
class ContractComposer {
  private val templateEngine = new ContractTemplateEngine()

  def compose(tenantId: String, baseTemplate: String, overrides: Map[String, String]): String = {
    val sandbox = new TenantSandbox(tenantId)

    // Parameter values from overrides can contain template directives
    // This enables meta-programming in contract composition
    val firstPass = templateEngine.resolveTemplate(baseTemplate, overrides, sandbox)

    // Second resolution pass for nested templates
    val secondPass = templateEngine.resolveTemplate(firstPass, Map.empty, sandbox)

    // Process legacy exec directives
    templateEngine.processLegacyDirectives(secondPass, sandbox)
  }
}
